public static void add(Node t, Node l, Node r){
    t.maxCnt = 0;
    t.secCnt = 0;

    if (l.max == r.max){
        t.max = l.max;
        t.maxCnt = l.maxCnt + r.maxCnt;
        t.sec = Math.max(l.sec, r.sec);
        if (t.sec == l.sec) t.secCnt += l.secCnt;
        if (t.sec == r.sec) t.secCnt += r.secCnt;
    } else if (l.max > r.max) {
        t.max = l.max;
        t.maxCnt = l.maxCnt;
        if (l.sec == r.max){
            t.sec = l.sec;
            t.secCnt = l.secCnt + r.maxCnt;
        } else if (l.sec > r.max) {
            t.sec = l.sec;
            t.secCnt = l.secCnt;
        } else {
            t.sec = r.max;
            t.secCnt = r.maxCnt;
        }
    } else {
        t.max = r.max;
        t.maxCnt = r.maxCnt;
        if (l.max == r.sec){
            t.sec = l.max;
            t.secCnt = l.maxCnt + r.secCnt;
        } else if (l.max > r.sec) {
            t.sec = l.max;
            t.secCnt = l.maxCnt;
        } else {
            t.sec = r.sec;
            t.secCnt = r.secCnt;
        }
    }
}
